/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
    Card,
    Stack,
    Button,
    Typography,
    TablePagination,
    IconButton,
    MenuItem,
    Popover,
} from '@mui/material';
// import { toast } from 'react-toastify';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';

// components
import Scrollbar from '../../components/scrollbar';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

// ----------------------------------------------------------------------

export default function Cms() {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search)
    const navigate = useNavigate();
    const [template, setTemplate] = useState([]);
    const [noDataFound, setNoDataFound] = useState();
    const [isDeleteOpen, setIsDeleteOpen] = useState(false);
    const [totalCount, setTotalCount] = useState(0);
    const [filters, setFilters] = useState({ });
    const [isLoading, setIsLoading] = useState(true);
    const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
    const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
    const { i18 } = useMyContext();

    const fetchData = async () => {
        setIsLoading(true);
        try {
            const res = await axios.get(`module/cms?_page=${page}&_limit=${rowsPerPage}`);
            if (res.status === 200) {
                setTemplate(res.data.data);
                setNoDataFound(res.data.status);
                setTotalCount(res?.data.totalCount || 0);
            } else {
                GenerateToastConfig(res.data.message);
            }
        } catch (err) {
            GenerateToastConfig(err?.response?.data?.message);
        } finally {
            setIsLoading(false); 
        }
    };

    const deleteModal = (ids) => {
        sessionStorage.setItem("userId", ids);
        setIsDeleteOpen(true);
    };

    const cmsDelete = async () => {
        const ids = sessionStorage.getItem("userId");
        try {
            const res = await axios.delete(`module/cms/${ids}`);
            if (res.status === 200) {
                setIsDeleteOpen(false);
                fetchData();
                GenerateToastConfig(res.data.message, 'info');
            } else {
                GenerateToastConfig(res.data.message);
            }
        } catch (err) {
            GenerateToastConfig(err?.response?.data?.message);
        }
    };

    const routes = (data) => {
        navigate('/dashboard/EditcmsTemplate', {
            state: { item: data },
        });
    };

    const Postroutes = () => {
        navigate('/dashboard/emailtemplate');
    };

    useEffect(() => {
        fetchData();
    }, [page, rowsPerPage, filters]);

    useEffect(() => {
        updateUrlParams({ page, limit: rowsPerPage });
    }, [page, rowsPerPage]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setPage(1);
        setRowsPerPage(parseInt(event.target.value, 10));
    };

    const ActionComponent = (cell) => {
        const value = cell?.getValue();
        const original = cell?.row?.original;
        const [anchorEl, setAnchorEl] = useState(null);
        const [menuRowId, setMenuRowId] = useState(null);

        const handleActionMenu = (event, rowId) => {
            setAnchorEl(event.currentTarget);
            setMenuRowId(rowId);
        };

        const handleActionMenuClose = () => {
            setAnchorEl(null);
            setMenuRowId(null);
        };

        return (
            <>
                <IconButton
                    sx={{
                        width: '37px',
                        height: '37px',
                        background: '#EBEBEB',
                        color: 'black',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderRadius: '50%',
                    }}
                    onClick={(event) => handleActionMenu(event, value)}
                >
                    <Iconify icon="mdi:dots-horizontal" />
                </IconButton>
                <Popover
                    anchorEl={anchorEl}
                    open={Boolean(anchorEl) && menuRowId === value}
                    onClose={handleActionMenuClose}
                    anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
                    transformOrigin={{ vertical: 'top', horizontal: 'right' }}
                    PaperProps={{
                        sx: { width: 140 },
                    }}
                >
                    <MenuItem onClick={() => routes(original)}>
                        <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
                    </MenuItem>
                    <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
                        <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
                    </MenuItem>
                </Popover>
            </>
        );
    }

    const columns = [
        {
            header: i18?.SETTINGSLIST?.SUBJECT || "Subject",
            id: "title",
            accessorKey: "title",
            showFilter: false, 
            cell: ({ row }) => <span>{row?.original?.title || "---"}</span>,
        },

        {
            header: i18?.SETTINGSLIST?.ACTION || "Action",
            id: "action",
            accessorKey: "_id",
            cell: ActionComponent,
        },
    ];

    // const columns = useMemo(() => COLUMNS, []);
    // const data = React.useMemo(() => template.map((user) => {
    //     return {
    //         title: user?.title,
    //         action: user,
    //     };
    // }), [template]);

    const handleFilterChange = (filterKey, value) => {
        setFilters((prev) => ({ ...prev, [filterKey]: value }));
        setPage(1);
      };

    return (
        <>
            <Helmet>
                <title>CMS | Admin</title>
            </Helmet>

            <Stack direction="row" alignItems="center" justifyContent="space-between" my={3}>
                <Typography variant="h4" gutterBottom>
                    {i18?.SETTINGSLIST?.CMS_TEMPLATES || "CMS Templates"}
                </Typography>
                <Button variant="contained" onClick={Postroutes} startIcon={<Iconify icon="eva:plus-fill" />}>
                    {i18?.SETTINGSLIST?.ADD_TEMPLATES || "Add Templates"}
                </Button>
            </Stack>
            <Card>
                <Scrollbar>
                    {/* <TanstackTable data={data} columns={columns} /> */}
                    <TanstackTableV8
                        data={template}
                        columns={columns}
                        filters={filters}
                        isLoading={isLoading}
                        onFilterChange={handleFilterChange}
                    />
                </Scrollbar>
            </Card>
            <TablePagination
                rowsPerPageOptions={[5, 10, 25]}
                component="div"
                count={totalCount || '0'}
                rowsPerPage={rowsPerPage}
                page={page - 1}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                sx={{
                    '.MuiTablePagination-selectLabel': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-displayedRows': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-actions': {
                        marginBottom: '6px',
                    }
                }}
            />
            <DeleteModal
                isDeleteOpen={isDeleteOpen}
                handleClose={() => setIsDeleteOpen(false)}
                handleDelete={cmsDelete}
            />
        </>
    );
}
